// Independently paraphrased history population; URLs checked 2026-09-07.
const s = (id, lineageId, sourceType, citation, url, locator) => ({sourceId: `history-${id}`, lineageId, sourceType, citation, url, locator, accessedDate: '2026-09-07', accessStatus: 'anonymous_full_content', reuseStatus: 'publicly_accessible_citation_only', permissionBasis: 'Publicly readable source; cited and independently paraphrased without reproducing source text or figures.', supports: ['history']});
const records = [];
const add = (n, history, sources) => records.push({wopId: `wop-${String(n).padStart(6, '0')}`, history, sources});
const kwolek = s('acs-kwolek', 'american-chemical-society', 'institutional_reference', 'American Chemical Society. Stephanie Kwolek (1923–2014).', 'https://www.acs.org/explore/women-scientists/stephanie-kwolek.html', 'Biography: 1965 liquid-crystalline polyamide discovery and applications.');
const nomex = s('dupont-nomex-50', 'dupont', 'manufacturer_technical_document', 'DuPont. Nomex Marks First 50 Years of Enabling Endless Possibilities (2017).', 'https://www.dupont.com/news/Nomex-celebrates-50th-anniversary.html', 'Anniversary account and paragraphs on protective apparel, electrical insulation and aerospace honeycomb.');
const twaron = s('teijin-timeline', 'teijin', 'manufacturer_technical_document', 'Teijin Aramid. The Teijin Aramid story.', 'https://www.teijinaramid.com/en/about-us', 'Milestones: 1973 polymerization, 1986 commercial production, 2000 acquisition and 2023 recycled feedstock.');
add(176, 'Aramids developed along distinct paths toward heat protection and high-strength reinforcement. DuPont dates the commercial history of Nomex to 1967; its meta-aramid fibers and papers found roles in protective clothing, electrical insulation and aircraft honeycomb. Stephanie Kwolek’s 1965 discovery of liquid-crystalline aromatic-polyamide solutions at DuPont opened the high-strength fiber route associated with Kevlar and its uses in tires, armor and sporting equipment. A separate European development led to Twaron: Teijin’s corporate history identifies Leo Vollbracht’s 1973 PPTA polymerization and commercial production in 1986. These milestones describe several related aromatic-polyamide materials, rather than one invention shared by every aramid.', [nomex, kwolek, twaron]);
add(177, 'PPTA’s history is closely associated with the development of high-strength para-aramid fibers. Stephanie Kwolek’s liquid-crystalline polyamide work at DuPont in 1965 enabled the fiber technology behind Kevlar, subsequently used in tires, protective armor, aerospace equipment and sports goods. An independent industrial line became Twaron: Teijin records Leo Vollbracht’s polymerization milestone in 1973 and commercial fiber production at Delfzijl and Emmen in 1986. Teijin acquired the Twaron business in 2000. Its reported 2023 production using recycled feedstock illustrates the later shift toward recovering material value as well as increasing fiber performance.', [kwolek, twaron]);
add(178, 'The commercial history of this meta-aramid is anchored by DuPont’s Nomex, introduced in 1967. Heat-resistant clothing became a major use for firefighters, military aircrew, racing drivers and industrial workers. Paper and pressboard opened a separate market in transformer, generator and motor insulation, while honeycomb structures supported lightweight aircraft interiors and other aerospace components. DuPont’s 2017 fiftieth-anniversary account documents how one polymer chemistry expanded through different physical forms and application engineering. The commercialization date concerns Nomex materials; it should not be read as the first synthesis date of every aromatic polyamide.', [nomex]);
add(179, 'Teijin developed the copolyaramid associated with Technora in 1974 and dates its market introduction to 1986. This is a separate history from the earlier PPTA fiber route. Its copolymer design supported applications involving repeated loading and abrasion, including automotive transmission belts, hoses, industrial ropes and composite reinforcement. Teijin also describes later use in offshore flexible pipes and umbilical hoses, protective fabrics and Mars-landing equipment. These developments trace the commercial Technora embodiment of this copolymer; the trade name does not denote all para-aramids.', [s('technora-brochure','teijin','manufacturer_technical_document','Teijin Aramid. What is Technora?','https://product.teijinaramid.com/technora-brochure/what-is-technora','Proven performance for over 40 years; development, market introduction and application list.')]);
add(180, 'NASA traces aromatic PBI to Carl Marvel’s research on high-temperature polymers in the late 1950s and further development with Herward Vogel in 1961. NASA and the U.S. Air Force supported textile development from 1963; NASA subsequently contracted Celanese to develop protective fabrics. Spaceflight uses during the 1970s and 1980s included clothing, webbing and tethers. PBI entered U.S. firefighting applications in 1978, and a dedicated commercial fiber plant opened in Rock Hill in 1983. Celanese sold the business to PBI Performance Products in 2005. Protective textiles remained important while the Celazole line extended PBI into high-temperature polymer components.', [s('nasa-pbi','nasa','public_report','NASA Spinoff. Polymer Fabric Protects Firefighters, Military, and Civilians (2008).','https://spinoff.nasa.gov/Spinoff2008/ps_3.html','Originating Technology, Partnership and Product Outcome sections.')]);
const pboPatent = s('sweeny-kwolek-pbo-pbt','dupont','patent','W. Sweeny and S. L. Kwolek, DuPont. Method for making PBO and PBT polymers. US4608427A (1986).','https://patents.google.com/patent/US4608427A/en','Bibliographic data; Background and Detailed Description: prior syntheses and replacement of terephthalic acid with reactive diesters.');
add(181, 'PBO emerged from the search for rigid, thermally stable polymers for high-strength fibers. A documented development milestone is Wilfred Sweeny and Stephanie Kwolek’s DuPont patent, filed in 1985 and published in 1986, improving an existing polyphosphoric-acid synthesis by using terephthalate esters. Thus this patent represents a process advance rather than the first discovery of PBO. Toyobo records the start of full-scale Zylon PBO-fiber production in 1998. The commercial fiber extended rigid-chain polymer research into reinforcing materials; Toyobo identifies automotive friction materials and industrial manufacturing equipment among its application targets.', [pboPatent,s('toyobo-zylon-history','toyobo','manufacturer_technical_document','Toyobo. Toyobo Story: Tracing 140 years.','https://www.toyobo-global.com/about/story/index.html','1998: full-scale production of Zylon PBO fiber.'),s('toyobo-zylon-auto','toyobo','manufacturer_technical_document','Toyobo. Zylon: automotive materials.','https://www.toyobo-global.com/seihin/car/contents/zylon/zylon.html','Applications in friction materials and industrial materials for automotive manufacturing.')]);
add(182, 'Poly(p-phenylene benzobisthiazole), often abbreviated PBT in the rigid-rod literature, was already under study as a high-strength, high-modulus and thermally stable material before the mid-1980s. DuPont’s Wilfred Sweeny and Stephanie Kwolek filed a process patent in 1985 that explicitly built on earlier PBT synthesis, including work reported in 1981. Their improvement addressed slow dissolution of terephthalic acid in polyphosphoric acid by substituting selected terephthalate esters. This establishes a documented stage in the development of the polymer for demanding structural materials; it does not establish a first commercial launch or imply the commercial history of the unrelated polyester also called PBT.', [pboPatent]);
add(183, 'Polyoxadiazole fiber research was established by the 1960s. Milliken’s public historical account points to A. H. Frazer and F. T. Wallenberger’s 1964 fiber study and V. V. Korschak and collaborators’ 1966 synthesis work. A later application milestone was Milliken’s introduction in 2015 of industrial protective fabric containing polyoxadiazole together with cotton and polyester. Its 2019 petition for a generic fiber designation explains the role of the fiber in clothing for workplaces with flame or electrical-arc exposure. Milliken was the fabric developer and user, not the manufacturer of the polymer fiber. This chronology concerns the aromatic fiber branch of the broader polyoxadiazole family.', [s('milliken-pod-petition','milliken','public_report','Milliken & Company. Corrected petition for a generic polyoxadiazole fiber designation, submitted to the Federal Trade Commission (April 2019).','https://search.ftc.gov/system/files/documents/petitions-quash/petition-milliken-company-rn-number/p928401correctedrequestmilliken.pdf','Petition pages 1–3: 2015 fabric sales, 1964 and 1966 publications, manufacturer distinction and fiber scope.')]);
add(184, 'Modacrylic fibers are a group of acrylonitrile copolymers with several commercial histories. A well-documented example is Kaneka’s Kanekalon/Kanecaron, manufactured at Takasago and marketed from 1957. Hairlike texture, colorability and flame resistance supported wigs, hairpieces, artificial fur, curtains, bedding and stuffed toys. In its 2014 annual report, Kaneka described an additional Malaysian manufacturing facility intended to supply hair-extension markets in Africa. This illustrates how development moved from introducing a new synthetic textile fiber to tailoring large-scale production to specific consumer uses. The 1957 date belongs to Kaneka’s product line, not a universal invention date for all modacrylic compositions.', [s('kaneka-modacrylic-history','kaneka','manufacturer_technical_document','Kaneka Corporation. Annual Report 2014.','https://www.kaneka.co.jp/topics/uploads/2014/09/2014_ar.pdf','Printed page 6: Establish a New Manufacturing Facility for Kanekalon/Kanecaron Modacrylic Fiber.')]);
add(185, 'Vinyon’s development belongs to the early industrial use of vinyl-chloride-rich resins as textile fibers. A concrete postwar milestone is Theophilus A. Feild Jr.’s Union Carbide and Carbon patent, filed in 1946 and published in 1951, for coloring vinyl-resin yarns without losing their useful physical properties. It builds on existing vinyl chloride–vinyl acetate fiber technology and addresses the difficulty of applying ordinary textile dyeing methods to these water-resistant fibers. By 1970, the U.S. National Bureau of Standards described vinyon principally as a bonding fiber for nonwoven fabrics, as well as in embossed carpets, pressed felts and waterproof clothing. These sources document established fiber technology and its uses rather than prove a unique first-invention date.', [s('vinyon-dye-patent','union-carbide','patent','T. A. Feild Jr. Process for dyeing vinyl resin textile articles. US2577846A (1951).','https://patents.google.com/patent/US2577846A/en','Filing and inventor information; Description and examples of vinyl chloride–vinyl acetate yarn dyeing.'),s('nbs-fibers-vinyon','national-bureau-of-standards','public_report','National Bureau of Standards. Fibers and Fabrics. Consumer Information Series 1 (1970).','https://nvlpubs.nist.gov/nistpubs/Legacy/CIS/nbscis1.pdf','Vinyon fiber discussion and trademark list.')]);
add(186, 'Elastane grew from the effort to replace heavy rubber threads in foundation garments with fine synthetic elastic fibers. Joseph Shivers developed the DuPont material that became Lycra during the 1950s; the National Inventors Hall of Fame identifies his work on segmented synthetic elastomers as the central breakthrough. The material spread from underwear into sportswear, fashion and other stretch textiles, with additional applications in healthcare, furnishings and automotive products. DuPont’s 2004 sale of its Invista synthetic-fibers business to Koch Industries transferred the Lycra business as part of a larger industrial reorganization. Lycra is one commercial lineage within the broader elastane or spandex family.', [s('shivers-spandex','national-inventors-hall-of-fame','institutional_reference','National Inventors Hall of Fame. Joseph C. Shivers Jr.: Lycra Fiber (Spandex).','https://www.invent.org/inductees/joseph-c-shivers-jr','Biography: 1950s development, replacement of rubber, applications and 2004 ownership change.')]);
add(187, 'Novoloid fiber’s commercial history is closely tied to Kynol. The Museum of Fine Arts conservation reference attributes its development in 1968 to Carborundum, followed by licensing to Nippon Kynol and American Kynol. The manufacturer’s history places this work in U.S. space-technology development and dates full-scale industrial production to 1982. Flame-resistant clothing and spacecraft were early application areas. Later product development included carbon fibers and activated carbon fibers derived from the phenolic precursor, extending use into filtration and adsorption. These dates concern the Kynol novoloid-fiber lineage; phenol-formaldehyde resins themselves have a substantially earlier history.', [s('mfa-kynol','museum-of-fine-arts-boston','institutional_reference','Museum of Fine Arts, Boston. Kynol. CAMEO.','https://cameo.mfa.org/wiki/Kynol','Description: 1968 Carborundum development, licensing and uses.'),s('kynol-manufacturer-history','gunei-chemical','manufacturer_technical_document','Gunei Chemical Industry. What is Kynol?','https://kynol.com/','What is Kynol: 1968 development, 1982 industrial production and product forms.')]);

const celluloseFilms = s('cci-film-history','canadian-conservation-institute','public_report','Canadian Conservation Institute. Care of Plastic Film-based Negative Collections. Technical Bulletin 35.','https://www.canada.ca/en/conservation-institute/services/conservation-preservation-publications/technical-bulletins/care-plastic-negative.html','Cellulose acetate film discussion and Table 5: acetate propionate, acetate butyrate and triacetate development and photographic uses.');
const cameoTable = s('mfa-polymer-table','museum-of-fine-arts-boston','institutional_reference','Museum of Fine Arts, Boston. General Characteristics of Polymers (2007).','https://cameo.mfa.org/images/a/a1/Download_file_369.pdf','Pages 1–2: cellulose ethers, commercial names and applications.');
const carbs = s('bemiller-carbohydrate-history','bemiller-purdue','open_journal','J. N. BeMiller. One Hundred Years of Commercial Food Carbohydrates in the United States. Journal of Agricultural and Food Chemistry 57 (2009), 8125–8129.','https://talcottlab.tamu.edu/wp-content/uploads/sites/108/2019/01/100-Years-of-Carbs-in-the-US.pdf','Page 8128: methylcellulose, carboxymethylcellulose and hydroxypropylcellulose commercialization.');
add(188, 'Regenerated cellulose developed through multiple ways of dissolving and re-forming plant cellulose. Charles Frederick Cross, Edward John Bevan and Clayton Beadle’s 1892 viscose patent became a foundation for the rayon and cellophane industries. Subsequent fiber development improved wet performance and changed solvent systems. Lenzing dates its first high-wet-modulus fiber to 1965 and large-scale lyocell production at Heiligenkreuz to 1997; it acquired the Tencel business in 2004. Textile fibers remained central, while regenerated films provided a separate use of the same underlying cellulose chemistry. These dates distinguish a particular viscose process from later regenerated-cellulose technologies rather than assigning the whole class one invention date.', [s('cross-bevan','science-museum-group','institutional_reference','Science Museum Group. Cross & Bevan.','https://collection.sciencemuseumgroup.org.uk/people/ap26785/cross-bevan','Biographical account: Cross, Bevan and Beadle, 1892 viscose patent and rayon/cellophane industries.'),s('lenzing-history','lenzing','manufacturer_technical_document','Lenzing. A look into Lenzing’s history.','https://www.lenzing.com/about-us/history/','1965 high-wet-modulus fiber, 1997 Heiligenkreuz lyocell plant and 2004 Tencel acquisition.')]);
add(189, 'Cellulose acetate was developed by Paul Schützenberger in 1865, decades before it became an important commercial plastic and fiber. The Museum of Fine Arts account identifies Eastman Kodak’s introduction of acetate safety film in 1908 and Dreyfus production by 1910 as early industrial milestones. British production of acetate textile fibers followed in 1919 under the Celanese name. Film, lacquers and transparent sheeting were joined by textile, eyewear, tool-handle and cigarette-filter applications. Its history therefore spans chemical discovery, film-base manufacture and fiber commercialization, with different dates for each rather than one date applicable to every acetate grade.', [s('mfa-cellulose-acetate','museum-of-fine-arts-boston','institutional_reference','Museum of Fine Arts, Boston. Cellulose acetate. CAMEO.','https://cameo.mfa.org/wiki/Cellulose_acetate','Description paragraphs on 1865 development, 1908 film, Dreyfus production and 1919 fiber; Applications.')]);
add(190, 'Cellulose triacetate’s photographic history followed earlier, less highly acetylated cellulose films. The Canadian Conservation Institute dates production to 1948, when it offered a more stable base than earlier acetates. By about 1950, many film manufacturers were making triacetate roll film. Motion-picture use persisted partly because acetate can break when a projector jams and can be spliced readily. This is the history of commercial film-base development, not a claim that the triacetate chemical structure was first synthesized in 1948.', [celluloseFilms]);
add(191, 'Cellulose is a natural material, so its history begins with human use and scientific identification rather than invention. Anselme Payen isolated and characterized the plant substance in work reported in 1838; the name cellulose entered the literature in 1839. Paper, textiles and construction materials made it an industrial raw material long before modern structural analysis. Nishikawa and Ono obtained cellulose-fiber X-ray diffraction patterns in 1913. Later milestones included VanderHart and Atalla’s 1984 recognition of two native cellulose allomorphs and diffraction studies resolving their structures. This scientific progression supported a broader understanding of the material used for fibers, paper and chemical derivatives.', [s('payen-history','american-chemical-society-cell','institutional_reference','ACS Cellulose and Renewable Materials Division. The Anselme Payen Award.','https://acscell.org/awards/the-anselme-payen-award/','Anselme Payen biography: 1838 report and 1839 naming.'),s('cellulose-characterization-history','rongpipi-penn-state','open_journal','S. Rongpipi, D. Ye, E. D. Gomez and E. W. Gomez. Progress and Opportunities in the Characterization of Cellulose. Frontiers in Plant Science 9 (2019), 1894.','https://www.frontiersin.org/journals/plant-science/articles/10.3389/fpls.2018.01894/full','Introduction and Revealing the Unit Cell Parameters of Cellulose: uses, 1913 diffraction and 1984 allomorph discovery.')]);
add(192, 'Cellulose acetate butyrate emerged from efforts to improve the durability of early cellulose-acetate materials. The Canadian Conservation Institute dates its photographic development to 1936, while the Museum of Fine Arts records commercial availability in 1938. It served as a film base, including X-ray film, and as a varnish and molding resin. Kodak’s work on mixed cellulose esters belongs to this photographic development; Eastman subsequently maintained CAB for uses beyond photographic negatives. The different development and commercialization dates concern stages of industrial adoption rather than competing dates for a single event.', [celluloseFilms,s('mfa-cab','museum-of-fine-arts-boston','institutional_reference','Museum of Fine Arts, Boston. Cellulose acetate butyrate. CAMEO.','https://cameo.mfa.org/wiki/Cellulose_acetate_butyrate','Description: commercial availability in 1938, film, varnish and molding uses.')]);
add(193, 'Cellulose acetate propionate was developed in Kodak’s search for cellulose esters with improved film-base behavior. The Canadian Conservation Institute dates development to 1927 and records Kodak roll-film use from 1927 to approximately 1949. This was one branch of mixed-ester development alongside cellulose acetate butyrate. Its early photographic history should be distinguished from later molded-plastic grades and from cellulose acetate’s nineteenth-century discovery.', [celluloseFilms]);
add(194, 'Cellulose nitrate became an important nineteenth-century route from plant material to manufactured plastics. Alexander Parkes established the Parkesine Company in 1866 to commercialize a material he had demonstrated through objects ranging from jewelry to cutlery. John Wesley Hyatt’s Celluloid followed around 1870 and spread into articles such as combs and motion-picture film. By 1890, Hilaire de Chardonnet was marketing cellulose-nitrate-based artificial silk. These are milestones in plastic and fiber manufacture, distinct from the earlier preparation of nitrated cellulose. The Museum of Fine Arts also records a substantial later role in lacquers, aircraft fabric coatings, adhesives and glossy paints.', [s('parkes-history','science-museum-group','institutional_reference','Science Museum. Alexander Parkes: Living in a Material World (2014).','https://blog.sciencemuseum.org.uk/alexander-parkes-living-in-a-material-world/','Parkesine Company opening in 1866 and examples of manufactured objects.'),s('acs-early-cellulose-plastics','american-chemical-society','institutional_reference','American Chemical Society. Bakelite: The World’s First Synthetic Plastic.','https://www.acs.org/education/whatischemistry/landmarks/bakelite.html','Early plastics history: Hyatt’s Celluloid in 1870 and Chardonnet artificial silk by 1890.'),cameoTable]);
add(195, 'Methyl cellulose belongs to the early industrial cellulose ethers. BeMiller’s historical review dates Dow’s commercial methylcellulose production to 1938. It became a useful substitute for natural gum and adhesive systems, with applications in paper sizing and textile and paper conservation. Dow’s Methocel, Hoechst’s Tylose and ICI’s Methofas illustrate several commercial development lines. Conservators also used methyl cellulose in cleaning poultices and as an adhesive. These milestones concern commercialization and adoption of the material; the 1938 date is specific to Dow’s production and does not identify the first laboratory preparation.', [carbs,cameoTable]);
add(196, 'Ethyl cellulose was the product with which Dow entered the plastics business in 1935, under the Ethocel name. Dow’s history describes substantial wartime use in telephone components, goggles, control knobs, aircraft parts and canteens. Its later uses included protective paper and textile coatings, inks and hot-melt adhesives. Pharmaceutical formulation offered another direction: a 1993 Sterling Drug patent by Steven Frisbee, Gregg Stetsko and Margaret Lawton used ethylcellulose-containing coatings to control drug release. These milestones trace the transition from molded cellulose plastic to a functional coating polymer, without treating Dow’s launch as the first synthesis of ethyl cellulose.', [s('dow-ethylcellulose-history','dow','manufacturer_technical_document','Dow. History of Dow: Timeline.','https://corporate.dow.com/en-us/about-dow/company/history/timeline.html','1935 entry: introduction of Ethocel ethylcellulose resins.'),s('dow-ethocel-wartime','dow','manufacturer_technical_document','Dow. Willard H. Dow: A Son Takes the Lead During Demanding Times.','https://corporate.dow.com/en-us/about-dow/company/history/willard-dow.html','Wartime uses of Ethocel.'),cameoTable,s('ethylcellulose-drug-release','sterling-drug','patent','S. E. Frisbee, G. Stetsko and M. A. Lawton. Oral sustained-release drug compositions. US5213811A (1993).','https://patents.google.com/patent/US5213811A/en','Inventor and filing data; Description and claims for ethylcellulose-containing release coatings.')]);
add(197, 'Hydroxyethyl cellulose entered industrial use during the early development of water-soluble cellulose ethers; the Museum of Fine Arts places it in the 1930s. Thickeners, emulsifiers and film formers for coatings, cosmetics and other formulations became major roles, with Cellosize, Natrosol and Tylose H among commercial lines. A documented manufacturing advance was Rayonier’s patent filed in 1959 by Reid Logan Mitchell, Arthur Albohn and Stig Palmgren. Published in 1962, it described continuous contact between alkali cellulose and ethylene oxide using a vibrating conveyor. This was a process-engineering contribution to an existing polymer, not its first synthesis.', [cameoTable,s('rayonier-hec','rayonier','patent','R. L. Mitchell, A. R. Albohn and S. G. Palmgren. Process and apparatus for producing hydroxyethylcellulose. US3045007A (1962).','https://patents.google.com/patent/US3045007A/en','Bibliographic data and Description: continuous vibratory-conveyor reaction process.')]);
add(198, 'Hydroxypropyl cellulose became an industrial cellulose ether through Hercules development associated with Eugene D. Klug. BeMiller dates its commercialization to 1966. A Klug patent filed in 1963 and published in 1966 documents process improvements in which propylene oxide served as both reagent and diluent. The commercial Klucel line subsequently supported thickening and film-forming uses in formulations, as well as paper sizing and leather consolidation in conservation. These developments link manufacturing control to a polymer soluble in selected aqueous and organic media; they should not be conflated with the invention of cellulose ethers as a whole.', [carbs,cameoTable,s('klug-hpc','hercules','patent','E. D. Klug. Hydroxypropyl cellulose and process. US3278520A (1966).','https://patents.google.com/patent/US3278520A/en','Bibliographic data and opening Description: process improvement and propylene oxide as diluent.')]);
add(199, 'Hydroxypropyl methylcellulose developed through the tailoring of mixed cellulose ethers to different solvents and applications. A 1974 Dow patent by George Greminger Jr., Carl Strange, Karl Krumel and James Hudson Jr. describes earlier commercial HPMC as a thickener for water-based paints and coatings. Their advance increased hydroxypropyl substitution to obtain grades soluble in anhydrous alcohol, addressing pharmaceutical-coating applications where water or chlorinated solvent mixtures were undesirable. Tablet coatings and water-soluble films therefore accompanied the established coatings-thickener role. The patent documents a particular grade-development milestone, not a first invention date for all HPMC.', [s('dow-hpmc-history','dow','patent','G. K. Greminger Jr., C. P. Strange, K. Krumel and J. Hudson Jr. Hydroxypropyl methylcellulose ethers and method of preparation. US3839319A (1974).','https://patents.google.com/patent/US3839319A/en','Inventor data; Background, Summary and Description: existing paint uses and alcohol-soluble grades for pharmaceutical coating.')]);
add(200, 'Carboxymethyl cellulose’s early history includes a German preparation patent issued in 1918. Hercules began commercial U.S. production in 1943, according to BeMiller’s historical review. Initially developed as a replacement for natural gums, it expanded into applications that used its ability to alter solution behavior. This chronology distinguishes the early patent from later industrial scale-up and explains why CMC belongs to the history of formulated products as much as to the history of plastics.', [carbs]);

const starchMilestones = s('aaccii-starch-milestones','cereals-and-grains-association','institutional_reference','D. R. Lineback, J. N. BeMiller and P. A. Seib. Carbohydrates. Cereal Foods World 59 (2014), 202–205.','https://www.cerealsgrains.org/meetings/archive/2015/overview/Documents/Carbohydrates.pdf','Pages 202–205: Schoch fractionation, high-amylose commercialization, waxy starch and amylopectin models.');
add(201, 'Starch is a natural plant material with a long history as food and adhesive. FAO’s historical account connects wheat-starch preparation with ancient Egyptian papyrus manufacture and identifies Kirchhoff’s 1811 conversion of starch to sugar by acid hydrolysis as an important chemical milestone. Later industries used starch in paper and textile sizing, coatings, adhesives and glucose manufacture as well as food. Wartime loss of tapioca supplies helped drive American Maize Products and National Starch Products to commercialize waxy maize starch in 1942. High-amylose maize followed commercially in 1958, extending the range available for formulated foods. These dates concern extraction, conversion and crop development rather than invention of starch.', [carbs,s('fao-starch-history','fao','public_report','FAO. Cassava processing: Utilization of cassava products.','https://www.fao.org/4/X5032E/x5032E06.htm','Cassava starch and its uses; Food industries; The glucose industry: historical use, industrial applications and 1811 acid hydrolysis.')]);
add(202, 'Amylose was identified through research on natural starch, rather than invented as a synthetic polymer. Thomas J. Schoch’s separation work in the 1940s established the distinction between its comparatively linear chains and branched amylopectin. In 1958, Bear Hybrids Corn Company, American Maize Products and National Starch and Chemical commercialized a high-amylose maize hybrid. Such crop development made amylose-rich ingredients accessible to industry. Research by Hizukuri and colleagues in 1981 subsequently demonstrated limited branching in amylose, refining the earlier structural picture.', [starchMilestones]);
add(203, 'Amylopectin’s history combines starch fractionation with development of waxy crop starches. Schoch’s work in the 1940s established its branched character. Waxy maize starch entered use during that decade to provide thickening with reduced gel formation. Later structural advances included the amylopectin cluster models proposed independently by Z. Nikuni in 1969 and Dexter French in 1971, followed by refinements from Robin and colleagues and Hizukuri. These were discoveries about a naturally produced polymer; commercialization concerned amylopectin-rich starch ingredients rather than a newly invented molecule.', [starchMilestones]);
add(204, 'Thermoplastic starch developed through efforts to turn starch into material processable with plastics equipment. A Novamont patent published in 1992 by Catia Bastioli, Vittorio Bellotti and Alessandro Montino documents one route: plasticized starch combined with synthetic thermoplastic polymers. This was part of a broader development field, not the invention date of every thermoplastic-starch grade. Novamont, established in 1990 from the Montedison research tradition, records a Mater-Bi biodegradable bag in 1992 and later packaging, foam and food-service applications. Mater-Bi illustrates the commercial history of starch-containing blends; its formulations should not be equated with pure plasticized starch.', [s('bastioli-starch-blends','novamont','patent','C. Bastioli, V. Bellotti and A. Montino. Biodegradable polymeric compositions based on starch and thermoplastic polymers. WO1992014782A1 (1992).','https://patents.google.com/patent/WO1992014782A1','Inventor and publication data; Description of plasticizers and starch/thermoplastic-polymer compositions.'),s('novamont-history','novamont','manufacturer_technical_document','Novamont. Our History.','https://www.novamont.com/eng/history','Timeline: 1990 establishment; 1992 bag; 1998 packaging; 2002 foam; 2012 food-service products.')]);
const chitinReview = s('elsoud-chitin-history','national-research-centre-egypt','open_journal','M. M. Abo Elsoud and E. M. El Kady. Current trends in fungal biosynthesis of chitin and chitosan. Bulletin of the National Research Centre 43, 59 (2019).','https://link.springer.com/article/10.1186/s42269-019-0105-y','Introduction; Fungal chitin and chitosan—Historical background; application sections.');
add(205, 'Chitin is naturally produced, so its chronology begins with scientific isolation. Henri Braconnot isolated material from mushrooms in 1811 and called it fungine; Odier introduced the name chitin in 1823. Later industrial recovery relied heavily on shrimp and crab shell wastes. Research broadened toward food, paper, textile and biomedical materials, while fungal fermentation offered an alternative to seasonal marine feedstocks. The 2019 review by Abo Elsoud and El Kady describes this transition from extraction of natural waste to controlled biological production. Chitin and its deacetylated derivative chitosan have connected but distinct histories.', [chitinReview]);
add(206, 'Rouget described chitosan formation in 1859, and Hoppe-Seyler proposed its name in 1894. Most manufactured chitosan has been obtained by deacetylating chitin from crustacean shells. A separate biological route developed when Araki and Ito described chitin-deacetylase activity in Mucor rouxii in 1974; White and colleagues advanced fungal-mycelium extraction in 1979. Subsequent research extended applications from industrial formulations toward wound dressings, drug-delivery systems and tissue-engineering supports. These uses include research-stage materials as well as commercial products; they do not imply that every proposed biomedical use was adopted clinically.', [chitinReview]);
add(207, 'E. C. C. Stanford’s 1881 discovery of alginic acid began the scientific and industrial history of this natural seaweed polymer. Early ventures included binders for anthracite dust and, by 1927, can-sealing materials in San Diego. The business was reorganized as Kelco in 1929. Production expanded in Britain during 1934–1939 and in Norway after the Second World War. Alginate subsequently became important in textile-printing pastes, paper products and food thickening and gelling. Stanford, F. C. Thornley and later Kelco developers helped move it from crude seaweed extract into controlled industrial ingredients. Propylene glycol alginate, developed through later esterification work, is a derivative rather than the original polymer.', [s('fao-alginate-history','fao','public_report','D. J. McHugh. Production, properties and uses of alginates. FAO Fisheries Technical Paper 288 (1987), Chapter 2.','https://www.fao.org/4/x5822e/x5822e04.htm','Extraction processes—Introduction; Uses; discussion of propylene glycol alginate.')]);
add(208, 'Agarose’s history concerns the separation and characterization of a natural agar component. Alfred Polson’s patent account credits C. Araki’s 1937 work with distinguishing agarose from agaropectin and cites subsequent structural studies, including Hjertén’s 1962 work. Polson’s process, filed in the United States in 1964 and patented in 1967 for the South African Inventions Development Corporation, used polyethylene glycol to fractionate agar. Purification supported electrophoresis, gel filtration, bacterial culture and virus-plaque work by reducing interfering components. This is a documented purification advance; agarose itself was not invented in 1967, and the older history of edible agar is not the same as that of purified laboratory agarose.', [s('polson-agarose','south-african-inventions-development','patent','A. Polson. Fractionation of mixtures of agarose and agaropectin. US3335127A (1967).','https://patents.google.com/patent/US3335127A/en','Bibliographic data; Description opening paragraphs on Araki and Hjertén; applications following fractionation examples.')]);
add(209, 'Carrageenan has roots in longstanding use of red seaweeds for jellies, milk puddings and adhesives. Stanford named the extracted material carrageenin in 1862; Bourgade’s 1871 process used alcohol precipitation to recover it. Twentieth-century development broadened both feedstocks and uses, including stabilization of chocolate milk. The introduction of Eucheuma farming in the Philippines in 1971 expanded supplies beyond traditional Irish-moss harvesting. Air-freshener gels became another significant application in the early 1970s. This chronology describes extraction and industrial development of a naturally occurring polysaccharide family, whose different seaweed sources yield different carrageenan structures.', [s('fao-carrageenan-history','fao','public_report','N. Stanley. Production, properties and uses of carrageenan. FAO Fisheries Technical Paper 288 (1987), Chapter 3.','https://www.fao.org/4/x5822e/x5822e05.htm','Sources; Extraction and recovery; Uses—air-freshener gels.')]);

add(210, 'Lignin is a natural component of wood, and its industrial history grew from separating cellulose during pulping. Borregaard provides one documented example of turning the resulting liquor into products: it began making vanillin from lignin in 1962 and, according to Norsk Industri’s historical account, commercial lignosulfonate production in spring 1968. During 1972–1983 it invested in recovering the lignin stream as chemicals following pressure to reduce river discharges. Concrete admixtures, gypsum-board additives, dye dispersants and feed binders became important outlets. This history concerns technical lignins and lignosulfonates recovered or modified during pulping, not the invention of native lignin.', [s('norsk-lignin-history','norsk-industri','public_report','Norsk Industri. Ringen sluttes: Mulighetsstudie for sirkulær økonomi i prosessindustrien (2019).','https://www.norskindustri.no/siteassets/dokumenter/rapporter-og-brosjyrer/mulighetsstudie-sirkular-okonomi-i-prosessindustrien.pdf','Printed pages 10–11, Borregaards lignin-historie: 1962 and 1968 production, 1972–1983 investment and applications.'),s('borregaard-lignin-functions','borregaard','manufacturer_technical_document','Borregaard. Lignin & Lignosulfonates.','https://www.borregaard.com/product-areas/lignin','Wood-derived lignin; history of industrial lignin chemicals; binder and dispersant functions.')]);
add(211, 'Collagen is an animal structural protein, not a human invention. Its modern molecular history includes competing models by Astbury and Bell in 1940 and Pauling and Corey in 1951. Ramachandran and Kartha proposed the essential triple-helix arrangement in 1954; Rich and Crick and North’s group refined it in 1955. Synthetic collagen-related peptides became structural probes from the late 1960s, and Berman’s group reported a high-resolution model-peptide crystal structure in 1994. Later research used this understanding to design collagen-like assemblies and tissue-supporting biomaterials. These advances concern molecular understanding and engineered collagen materials, distinct from the much older use of animal tissues.', [s('shoulders-raines-collagen-history','raines-laboratory','open_journal','M. D. Shoulders and R. T. Raines. Collagen Structure and Stability. Annual Review of Biochemistry 78 (2009), 929–958; author-hosted full text.','https://raineslab.com/sites/default/files/labs/raines/pdfs/Shoulders2009a.pdf','Pages 930–931: structural chronology; pages 947–949: collagenous biomaterials and synthetic assemblies.')]);
add(212, 'Silk fibroin is a natural protein with a textile history extending into antiquity. The Metropolitan Museum preserves Chinese woven silk dated to the Warring States period, 475–221 BCE. Silk later supplied Byzantine court and ecclesiastical clothing, with state and private workshops developing elaborate woven fabrics. Modern research sought to recover fibroin for uses beyond textiles. A documented process advance came from Jen-Chang Yang and colleagues at Taipei Medical University: their patent, filed in 2010 and granted in 2012, used precipitation under shear to recover fibroin without conventional dialysis. It addressed a production bottleneck for regenerated material. The patent describes application directions including cell-culture supports, wound-dressing membranes and tissue-engineering materials. These developments concern processing a natural protein and proposed biomedical uses, not an invention of silk itself.', [s('met-ancient-silk-history','metropolitan-museum-art','institutional_reference','The Metropolitan Museum of Art. Textile with Stripes and Confronted Dragons; object 2002.559.','https://www.metmuseum.org/art/collection/search/64883','Object date, material and curatorial description: Chinese woven silk of the Warring States period.'),s('met-byzantine-silk-history','metropolitan-museum-art','institutional_reference','N. H. Munroe. Woven Silk. The Metropolitan Museum of Art (25 June 2012).','https://www.metmuseum.org/exhibitions/listings/2012/byzantium-and-islam/blog/material-matters/posts/woven-silk','Historical discussion: Byzantine court and ecclesiastical clothing, workshops and textile development.'),s('tmu-silk-fibroin-history','taipei-medical-university','patent','J.-C. Yang and colleagues. High yield dialysis-free process for producing organosoluble regenerated silk fibroin. US8309689B2 (2012).','https://patents.google.com/patent/US8309689B2/en','Bibliographic data; Background on 2003–2004 regenerated-fiber research and applications; Summary of dialysis-free precipitation.')]);
const phaReview = s('yousefi-wnek-pha-history','miami-university-case-western','open_journal','A. M. Yousefi and G. E. Wnek. Poly(hydroxyalkanoates): Emerging Biopolymers in Biomedical Fields and Packaging Industries for a Circular Economy. Biomedical Materials & Devices 3 (2025), 19–44; published online 2024.','https://link.springer.com/article/10.1007/s44174-024-00166-4','PHA historical milestones and Figure 2; P(3HB) and P(3HB-co-3HV) sections; packaging and biomedical applications.');
add(213, 'PHA research grew from observations of bacterial storage granules. Maurice Lemoigne’s studies in the 1920s identified the polyester now called poly(3-hydroxybutyrate); subsequent work established a much broader family of microbial polyesters. Macrae and Wilkinson clarified the storage role in 1958, and W. R. Grace attempted commercial production from 1959. Later work varied microbial strains and monomer composition to expand material behavior. Packaging, agricultural products and biomedical materials became major development directions. This family history begins with discovery of natural polymers; individual PHA homopolymers and copolymers have separate commercialization histories.', [phaReview]);
add(214, 'PHB was identified through Maurice Lemoigne’s bacterial research during the 1920s. In 1958, Macrae and Wilkinson helped establish its role as a microbial carbon and energy reserve; W. R. Grace explored industrial production from 1959. By 1982, published work was comparing its material behavior with polypropylene and investigating biodegradability and biocompatibility. These developments encouraged interest in packaging and biomedical materials, while brittleness and processing limitations helped motivate copolymer development. PHB is therefore a discovered microbial polymer subsequently developed as a plastic; the later Biopol PHBV copolymer should not be treated as chemically identical to PHB.', [phaReview]);
add(215, 'PHBV developed as a way to modify the behavior of bacterial PHB through a second monomer. Imperial Chemical Industries’ Paul A. Holmes, Stephen H. Collins and Leonard F. Wright documented fermentation-based 3-hydroxybutyrate copolymers in a patent family with a 1981 priority date, including hydroxyvalerate-containing materials. Its U.S. patent was published in 1984. Later commercial PHBV was known as Biopol; Procter & Gamble’s 2000 patent describes that existing ICI material and earlier efforts to make films for diaper backsheets. These records trace the shift from a microbial storage polyester toward processable disposable-product materials, without assigning all PHBV formulations one invention date.', [s('ici-phbv-history','imperial-chemical-industries','patent','P. A. Holmes, S. H. Collins and L. F. Wright. 3-Hydroxybutyrate polymers. US4477654A (1984).','https://patents.google.com/patent/US4477654A/en','Bibliographic data; Description: fermentation and 3-hydroxybutyrate/3-hydroxyvalerate copolymers.'),s('pg-phbv-context','procter-and-gamble','patent','Procter & Gamble. Biodegradable PHA copolymers. US6077931A (2000).','https://patents.google.com/patent/US6077931A/en','Background: ICI Biopol PHBV and prior film-development work for diaper backsheets.')]);
add(216, 'Kaneka began developing this hydroxybutyrate/hydroxyhexanoate copolymer in the early 1990s. Its researchers identified a producing microorganism in soil at the company’s Takasago site, then combined strain development and polymer engineering to improve production. This documents Kaneka’s development route rather than a universal first discovery date. The resulting Green Planet PHBH line expanded into straws, shopping bags, cutlery and food packaging. Collaborations with Japan Airlines and Seven-Eleven illustrate adoption, while a Shiseido cosmetics-container project began in 2019. The history is one of fermentation scale-up followed by application development; the trade name denotes Kaneka’s materials within the copolymer class.', [s('kaneka-phbh-history','kaneka','manufacturer_technical_document','Kaneka. How does KANEKA Biodegradable Polymer Green Planet make the world healthy?','https://www.kaneka.co.jp/en/solutions/phbh/index.html','Development Story: early-1990s program and Takasago microorganism; Widespread Uses and collaboration examples.')]);
add(217, 'Polylactide’s development predates its modern packaging market. George Lowrance Dorough’s DuPont patent, filed in 1931 and issued in 1935, documents lactide resins for coating compositions and cellulose-derivative formulations. Allan K. Schneider’s DuPont work, filed in 1951 and patented in 1955, advanced stronger polymers from purified high-melting lactide. The later growth of large-scale fermentation and polymer manufacture changed the economics: NatureWorks dates its Blair, Nebraska plant to 2002. Its Ingeo materials expanded into packaging, food-service ware, fibers, durable goods and 3D-printing filament. These milestones distinguish early resin chemistry from subsequent industrial scale and application development.', [s('dorough-pla','dupont','patent','G. L. Dorough. Polymeric lactide resin. US1995970A (1935).','https://patents.google.com/patent/US1995970A/en','Bibliographic data; Description: lactide resins and coating/cellulose-derivative uses.'),s('schneider-lactide','dupont','patent','A. K. Schneider. Polymers of high melting lactide. US2703316A (1955).','https://patents.google.com/patent/US2703316A/en','Bibliographic data; Description: purified lactide and improved polymers.'),s('natureworks-history','natureworks','manufacturer_technical_document','NatureWorks. About.','https://natureworksllc.com/about','Blair plant commissioning in 2002; applications development and Ingeo markets.')]);
const schneiderSutures = s('schneider-sutures','ethicon','patent','A. K. Schneider. Polylactide sutures. US3636956A (1972).','https://patents.google.com/patent/US3636956A/en','Related application history from 1962; Description, L-lactide examples and glycolide copolymer claims.');
add(218, 'Poly(L-lactide)’s medical development is documented in Allan K. Schneider’s Ethicon patent on polylactide sutures. Issued in 1972, it traces related applications back to 1962 and describes drawing and annealing L-lactide-polymer filaments to obtain absorbable surgical materials. The program addressed the handling, strength and dimensional stability needed for tissue joining. It also covered lactide/glycolide copolymers, which must be distinguished from PLLA homopolymer. This provides a dated application-development milestone for the stereoregular polymer; it is not a claim that PLLA was first synthesized in 1962 or that all modern PLA packaging grades are pure PLLA.', [schneiderSutures]);

add(219, 'A pivotal application of polyglycolic acid was the synthetic absorbable suture. Edward Emil Schmitt and Rocco Albert Polistina filed American Cyanamid’s surgical-suture patent in 1963; it was granted in 1967. The work addressed the need for reproducible fibers that could hold tissue and subsequently be absorbed, a different milestone from the polymer’s first chemical preparation. Later material development broadened beyond surgical thread. Kureha’s Kuredux technical literature documents commercial PGA resins for films, molded parts and bottle applications, including grades with controlled hydrolysis. The polymer’s history thus spans medically useful degradation and the development of processable barrier materials.', [s('cyanamid-pga-sutures','american-cyanamid','patent','E. E. Schmitt and R. A. Polistina. Surgical sutures. US3297033A (1967).','https://patents.google.com/patent/US3297033A/en','Bibliographic data; Description of glycolic-acid polyester fibers and tissue-joining application.'),s('kuredux-history-applications','kureha','manufacturer_technical_document','Kureha Corporation. Kuredux technical information.','https://www.kuredux.com/pdf/Kuredux_technical_EN.pdf','Printed page 1: commercial PGA grades and bottle use; pages 4 and 9–11: barrier and processing development.')]);
add(220, 'Lactide/glycolide copolymers were part of the development of synthetic absorbable surgical materials during the 1960s. Allan K. Schneider’s Ethicon patent, issued in 1972 with related applications dating to 1962, describes lactide-rich copolymers containing glycolide for sutures and other tissue-supporting devices. Extrusion, drawing and annealing were integral to turning the polymer into a useful fiber. This documents one early application lineage within PLGA, whose composition can vary widely. It should not be interpreted as a first synthesis date for every lactide/glycolide ratio or as evidence that all PLGA grades behave like the specific suture compositions.', [schneiderSutures]);
add(221, 'Polycaprolactone’s industrial development included new ways to polymerize cyclic esters. Eugene F. Cox and Fritz Hostettler’s Union Carbide patent, filed in 1959 and issued in 1962, demonstrated caprolactone polymerization using metal-amide catalysts. This was a synthesis advance within an existing lactone-polymer field. Later commercial materials served both as thermoplastic polymers and as polyols for other resins. Perstorp’s 2008 Capa expansion announcement describes uses in coatings, cast elastomers, hot-melt adhesives, footwear supports and orthopedic braces. Perstorp sold the Capa business, including its Warrington manufacturing site, to Ingevity in 2019, continuing the commercial development of the product family.', [s('carbide-caprolactone','union-carbide','patent','E. F. Cox and F. Hostettler. Polymerization of cyclic esters. US3021311A (1962).','https://patents.google.com/patent/US3021311A/en','Bibliographic data; Description and examples for epsilon-caprolactone polymerization.'),s('perstorp-capa-2008','perstorp','manufacturer_technical_document','Perstorp. Perstorp to expand caprolactone production by 2010 (3 June 2008).','https://www.perstorp.com/en/news_center/pressreleases/2008/20080603_expand_caprolactone','Announcement: Capa monomer/polyol production and application list.'),s('perstorp-capa-sale','perstorp','manufacturer_technical_document','Perstorp. Perstorp completes sale of Capa (14 February 2019).','https://www.perstorp.com/en/news_center/news/2019/perstorp_completes_sale_of_capa/','Sale of caprolactone business and Warrington facility to Ingevity.')]);
const pbsFibers=s('showa-polyester-fibers','showa-highpolymer','patent','T. Takahashi, H. Uda, A. Nakamura, R. Kamei and E. Takiyama. Polyester fibers. US5349028A (1994).','https://patents.google.com/patent/US5349028A/en','Bibliographic data; Description and claims: succinate and succinate/adipate polyester fibers, chain extension and nonwoven uses.');
const biopbs=s('pttmcc-biopbs-development','ptt-mcc-biochem','manufacturer_technical_document','PTT MCC Biochem. BioPBS brochure (2025 revision).','https://pttmcc.com/file_upload/brochure/PTTMCC_BioPBS_Brochure2P_2025Revised.pdf','Company profile and resin life cycle; PBS/PBSA grade distinction; application introduction.');
add(222, 'PBS became an important target of biodegradable-polyester development in Japan. Showa Highpolymer’s patent work, with priority claims from 1992 and a U.S. grant in 1994, developed succinate-based polyester fibers through molecular-weight control and melt processing. A later Hitachi Plant Technologies patent, published in 2012, addressed continuous PBS manufacturing through staged polycondensation reactors. The BioPBS line licensed from Mitsubishi Chemical subsequently incorporated bio-derived succinic acid into commercial production in Thailand. Its documented applications include coated paper, packaging, fibers and molded food-service items. These milestones concern industrial processing and renewable feedstocks, not a claim that PBS first existed in the 1990s.', [pbsFibers,s('hitachi-pbs-history','hitachi','patent','M. Kamikawa and colleagues. Device and method for producing polybutylene succinate. US20120202962A1 (2012).','https://patents.google.com/patent/US20120202962A1/en','Bibliographic assignment and date; Background and Summary: staged continuous polycondensation.'),biopbs]);
add(223, 'PBAT’s commercial history is anchored by BASF’s introduction of ecoflex in 1998. The aliphatic–aromatic copolyester became a flexible component for compostable films and compounds, including combinations with starch and PLA. Packaging and agricultural films, shopping and organic-waste collection bags, and paper coatings were important application directions. BASF’s later ecovio compounds used PBAT to contribute flexibility and toughness; its 2023 anniversary account describes further paper-packaging grade development. These dates document a commercial product lineage, not the first preparation of every adipate/terephthalate copolyester. They also illustrate that biodegradable performance and renewable feedstock content are separate features of a material.', [s('basf-pbat-history','basf','manufacturer_technical_document','BASF. BASF celebrates 25th birthday of ecoflex, the world’s first PBAT biopolymer (6 October 2023).','https://www.basf.com/global/en/media/news-releases/2023/10/p-23-321','Opening paragraphs; ecoflex/ecovio blending and market applications; 2023 paper-packaging development.')]);
add(224, 'PBSA developed alongside PBS as manufacturers varied aliphatic-polyester composition for flexible materials. Showa Highpolymer’s 1994 polyester-fiber patent includes succinate/adipate chemistry and describes turning such polymers into fibers and nonwoven products. More recent BioPBS literature from PTT MCC Biochem distinguishes PBSA grades from PBS and documents packaging-film, fiber and molded-product development using technology licensed from Mitsubishi Chemical. Biomedical exploration formed a separate branch: Simon Williams and colleagues at Tepha included PBSA among the PBS copolymers in a 2021 patent publication on implant materials. That patent represents an investigated application, not evidence of routine clinical adoption or a first synthesis date.', [pbsFibers,biopbs,s('tepha-pbsa-history','tepha','patent','S. F. Williams and colleagues. Articles of poly(butylene succinate) and copolymers thereof. US20210244860A1 (2021).','https://patents.google.com/patent/US20210244860A1/en','Bibliographic data; Definitions of PBS copolymers and PBSA; Description and claims for implant forms.')]);
add(225, 'PEF’s recent development has centered on making its furan-based monomer available at industrial scale. Avantium records proof of its YXY conversion technology in 2006, an FDCA pilot plant and a first PEF bottle in 2011, and the formation of the Synvina venture with BASF in 2016. Avantium regained full ownership in 2019. Led technically by researchers including Gert-Jan Gruter, the program developed partnerships for bottles, films, packaging and textiles. The FDCA flagship plant was inaugurated in October 2024, when Releaf was introduced as the PEF brand. These are scale-up and commercialization milestones, distinct from the first laboratory synthesis of a furan polyester.', [s('avantium-pef-history','avantium','manufacturer_technical_document','Avantium. History.','https://avantium.com/our-company/history/','Timeline: 2006, 2011, 2014, 2016, 2019 and 2024; application and partner history.')]);

add(226, 'High-molecular-weight PEO advanced through manufacturing work on water-soluble polyethers during the 1950s. Frederick E. Bailey Jr. and John T. Fitzpatrick’s Union Carbide patent, filed in 1957 and granted in 1960, improved catalyst removal while retaining readily handled granular polymer. It describes established uses as thickeners, sizing agents and binders. Later development extended this solution behavior to medicines: Alan E. Royce’s 1993 Sandoz patent used PEO as a directly compressible tablet matrix to regulate drug release. These records document industrial purification and pharmaceutical formulation milestones, rather than the first preparation of the ethylene-oxide polymer family.', [s('carbide-peo-history','union-carbide','patent','F. E. Bailey Jr. and J. T. Fitzpatrick. Process for treating poly(alkylene oxide). US2941963A (1960).','https://patents.google.com/patent/US2941963A/en','Bibliographic data; opening Description: granular PEO, residual catalyst and thickener, size and binder uses.'),s('sandoz-peo-history','sandoz','patent','A. E. Royce. Directly compressible polyethylene oxide vehicle for preparing therapeutic dosage forms. US5273758A (1993).','https://patents.google.com/patent/US5273758A/en','Bibliographic data; Background and Summary: direct compression and drug-release control.')]);
add(227, 'Poly(propylene oxide) development has been closely connected to polyether catalysts and polyurethane raw materials. Robert J. Herold at General Tire & Rubber filed a double-metal-cyanide catalyst patent in 1963, granted in 1966, that included propylene-oxide polymerization. Herold and Robert E. Bingham’s 1982 patent subsequently addressed catalyst-residue treatment in polypropylene-ether polyols. This helped make the products suitable for subsequent reactions and polyurethane manufacture, including foams and elastomeric materials. The dated advances concern catalyst and purification technology within an existing polyether field; hydroxyl-terminated PPO polyols, high-molecular-weight PPO and PPO-containing copolymers should not be treated as one commercial grade.', [s('herold-ppo-catalyst','general-tire','patent','R. J. Herold. Method of making a polyether using a double metal cyanide complex compound. US3278459A (1966).','https://patents.google.com/patent/US3278459A/en','Bibliographic data; Description and propylene-oxide examples.'),s('herold-bingham-polyols','general-tire','patent','R. J. Herold and R. E. Bingham. Method for treating polypropylene ether and poly-1,2-butylene ether polyols. US4355188A (1982).','https://patents.google.com/patent/US4355188A/en','Background and Summary: catalyst residues, further reaction and polyurethane applications.')]);
add(228, 'PTMEG became an important intermediate for polyurethane and polyester manufacture before the late 1970s. Gerfried Pruckmayr and Robert H. Weir’s DuPont patent, filed in 1977 and granted in 1978, explicitly describes that established industrial position. Their advance used a separable polymeric acid catalyst to polymerize tetrahydrofuran, addressing catalyst recovery and disposal. BASF’s later PolyTHF materials illustrate the range of applications developed around this intermediate: spandex fibers, polyurethane hoses, films and cable sheathing, and elastomers for skate wheels. These are manufacturing and market milestones; the 1978 patent improved an existing material rather than marking PTMEG’s invention.', [s('dupont-ptmeg-history','dupont','patent','G. Pruckmayr and R. H. Weir. Method for preparing poly(tetramethylene ether) glycol. US4120903A (1978).','https://patents.google.com/patent/US4120903A/en','Bibliographic data; Background and Summary: established uses and reusable polymeric-acid catalyst.'),s('basf-polythf-history','basf','manufacturer_technical_document','BASF. PolyTHF—Polytetrahydrofuran.','https://products.basf.com/global/en/ci/polythf','Product introduction; spandex-fiber and thermoplastic-polyurethane application sections.')]);
add(229, 'PHEMA’s defining application history grew from Otto Wichterle’s work on water-swollen materials for eye implants in the 1950s. Wichterle and Drahoslav Lím’s hydrophilic-polymer patent, filed in 1960 and granted in 1965, documents crosslinked gels and biomedical articles. In 1961 Wichterle developed a spin-casting process for soft contact lenses using homemade equipment, turning a promising gel into reproducible optical shapes. Bausch & Lomb acquired manufacturing rights in 1966, providing a major commercial development route. These milestones concern PHEMA-based hydrogels and lens manufacture; the invention of the lens-making process is distinct from the initial polymer chemistry.', [s('wichterle-lim-hydrogel','wichterle-lim','patent','O. Wichterle and D. Lím. Cross-linked hydrophilic polymers and articles made therefrom. US3220960A (1965).','https://patents.google.com/patent/US3220960A/en','Bibliographic data; Description: hydroxyethyl methacrylate hydrogels and biomedical articles.'),s('nihf-wichterle','national-inventors-hall-of-fame','institutional_reference','National Inventors Hall of Fame. Otto Wichterle.','https://www.invent.org/inductees/otto-wichterle','Biographical account: 1950s gel research, 1961 spin casting and 1966 Bausch & Lomb rights acquisition.')]);
add(230, 'A landmark in PNIPAM research was M. Heskins and J. E. Guillet’s 1968 investigation of its unusual aqueous phase behavior. Heating-induced changes in solubility and chain dimensions made it a model temperature-responsive polymer. Subsequent research pursued gel actuators, drug-delivery materials and tissue-engineering systems, with applications depending on polymer form and formulation. Molecular interpretation remained active: Patrick K. Quoika and colleagues’ 2023 simulation study examined how the water model changes predicted thermal behavior. This history concerns the recognition and development of responsiveness, rather than identifying 1968 as the first synthesis or implying that all proposed biomedical applications became commercial products.', [s('quoika-pnipam-history','technical-university-munich-innsbruck','open_journal','P. K. Quoika and colleagues. Water model determines thermosensitive and physicochemical properties of poly(N-isopropylacrylamide) in molecular simulations. Frontiers in Materials 10, 1005781 (2023).','https://www.frontiersin.org/journals/materials/articles/10.3389/fmats.2023.1005781/full','Introduction: Heskins–Guillet 1968 and application context; Results and Conclusion: water-model sensitivity.')]);
add(231, 'PDADMAC belongs to the water-soluble polycations developed through diallyl-monomer polymerization. George B. Butler’s patent for Peninsular ChemResearch, filed in 1962 and granted in 1966, documents high-molecular-weight diallyldimethylammonium chloride polymers and their preparation. The work described applications in water clarification, paper wet-strength improvement and textile treatment. Nalco subsequently advanced industrial preparation: Wood E. Hunter and Theodore P. Sieder’s 1979 patent addressed monomer purification and polymerization in salt-containing solutions. These records trace laboratory polymer development into water-treatment manufacturing; they document specific advances rather than establishing one universal invention date for all diallyl-ammonium polymers.', [s('butler-pdadmac-history','peninsular-chemresearch','patent','G. B. Butler. Water soluble quaternary ammonium polymers. US3288770A (1966).','https://patents.google.com/patent/US3288770A/en','Bibliographic data; Examples I–III and concluding Description: water clarification, paper and textile uses.'),s('nalco-pdadmac-history','nalco','patent','W. E. Hunter and T. P. Sieder. Preparation of diallyl dimethyl ammonium chloride and polydiallyl dimethyl ammonium chloride. US4151202A (1979).','https://patents.google.com/patent/US4151202A/en','Bibliographic data; Description and claims: monomer purification and salt-containing polymerization.')]);
add(232, 'Polyethyleneimine developed as an industrial polyamine and later became a major research tool for nonviral gene delivery. BASF’s branched Lupasol materials illustrate established roles in adhesion promotion, lamination inks and improving dye acceptance. A distinct biomedical development line followed Boussif and colleagues’ 1995 DNA-complexation work. Thomas Kissel, Dagmar Fischer, Hans-Peter Elsässer and Thorsten Bieber subsequently developed lower-molecular-weight PEI for gene-transfer studies; their patent family claims priority from 1997 and was granted in Europe in 2006. This progression connects surface-binding chemistry with nucleic-acid delivery research, without assigning the gene-delivery date to PEI’s original synthesis or implying clinical adoption of every formulation.', [s('basf-lupasol-history','basf','manufacturer_technical_document','BASF. Lupasol.','https://products.basf.com/global/en/em/lupasol','Product description and applications: adhesion, lamination inks and dye acceptance.'),s('kissel-pei-history','kissel-fischer-elsasser-bieber','patent','T. Kissel, D. Fischer, H.-P. Elsässer and T. Bieber. Production of a low molecular weight polyethyleneimine. EP0905254B1 (2006).','https://patents.google.com/patent/EP0905254B1/en','Bibliographic data; Background and DNA-complexation experiments referencing Boussif et al. (1995).')]);

add(233, 'Sodium polystyrenesulfonate was among the water-soluble polymers explored during the expansion of industrial emulsion polymerization. John W. Vanderhoff and Ralph M. Wiley’s Dow Chemical patent, filed in 1959 and issued in 1966, includes its preparation as a water-in-oil latex. This records an early manufacturing route rather than establishing the polymer’s first synthesis. Later applications included aqueous pigment dispersion, textile finishing, antistatic treatment and water treatment. Shinji Ozoe, Kenichi Yamanoi and Hideaki Matsunaga at Tosoh Organic Chemical addressed monomer purity in a patent with 2012 priority, granted in 2016. Controlling iron and isomer impurities improved polymer color, an important consideration for adhesives and finishing products.', [s('dow-pss-history','dow','patent','J. W. Vanderhoff and R. M. Wiley. Water-in-oil emulsion polymerization process for polymerizing water-soluble monomers. US3284393A (1966).','https://patents.google.com/patent/US3284393A/en','Bibliographic data; Example 20: poly(sodium styrene sulfonate) latexes.'),s('tosoh-pss-history','tosoh-organic-chemical','patent','S. Ozoe, K. Yamanoi and H. Matsunaga. High-purity sodium p-styrenesulfonate and production process therefor. US9505713B2 (2016).','https://patents.google.com/patent/US9505713B2/en','Bibliographic data; Background and Summary: polymer applications, iron/isomer impurities and hue.')]);
add(234, 'The PFSA ionomer family grew from DuPont’s fluoropolymer and ion-exchange research during the 1960s, associated particularly with Walther Grot and the Nafion product line. Chemours’ company history connects that development with chlorine production and fuel-cell membranes. Further work tuned membrane selectivity: Grot’s DuPont patent, filed in 1971 and granted in 1974, modified one surface of a sulfonyl-containing fluoropolymer film to a sulfonamide form. Such chemical differentiation addressed the competing demands of ion transport and selectivity. Chlor-alkali electrolysis remained a major industrial application, with later Nafion products marketed by Chemours. These milestones describe the Nafion development lineage within PFSA, whose members include differing side-chain structures and membrane formulations.', [s('chemours-pfsa-history','chemours','manufacturer_technical_document','Chemours. Advanced Performance Materials: history and milestones.','https://www.chemours.com/en/about-chemours/our-businesses/advanced-performance-materials','Historical timeline: Nafion and Walther Grot; chlorine-production and fuel-cell applications.'),s('grot-pfsa-membrane','dupont','patent','W. Grot. Films of fluorinated polymer containing sulfonyl groups with one surface in the sulfonamide or sulfonamide salt form and a process for preparing such. US3784399A (1974).','https://patents.google.com/patent/US3784399A/en','Bibliographic data; Description: fluorinated ion-exchange films, surface modification and selectivity.'),s('nafion-chloralkali-history','chemours','manufacturer_technical_document','Chemours. Nafion membranes for chlor-alkali production.','https://www.nafion.com/en/industries/chlor-alkali','Chlor-alkali membrane applications and commercial development context.')]);
add(235, 'SPEEK developed as a functional derivative of PEEK for membrane applications. Martin James Peer’s PCI Membrane Systems patent application, published in 1989 with 1988 priority, describes blends of SPEEK with compatible polymers to make hydrophilic membranes for reverse osmosis, ultrafiltration and microfiltration. It also acknowledges earlier SPEEK membrane work, so the filing is an application-development milestone rather than a first synthesis claim. Later researchers investigated SPEEK as an aromatic alternative to perfluorinated proton-exchange membranes for fuel cells. Madhusmita Tripathy, P. B. Sunil Kumar and Abhijit P. Deshpande’s 2017 study at IIT Madras used molecular simulation to examine hydration, water-domain connectivity and transport, illustrating the shift from membrane fabrication toward understanding its conducting pathways.', [s('pci-speek-history','pci-membrane-systems','patent','M. J. Peer. Polymer blends. EP0337626A1 (1989).','https://patents.google.com/patent/EP0337626A1/ja','Bibliographic data; English Description: SPEEK membrane antecedents, compatible blends and filtration applications.'),s('iit-speek-history','iit-madras','preprint','M. Tripathy, P. B. Sunil Kumar and A. P. Deshpande. Molecular Structuring and Percolation Transition in Hydrated Sulfonated Poly(ether ether ketone) Membranes (2017).','https://arxiv.org/pdf/1701.06746','Introduction and Conclusions: SPEEK proton-exchange membranes and hydration-dependent connectivity.')]);
add(236, 'Poly(2-oxazoline) synthesis emerged from independent ring-opening-polymerization studies in 1966–1967. The early groups included D. A. Tomalia and D. P. Sheetz; W. Seeliger and colleagues; T. Kagiya and colleagues; and T. G. Bassiri, A. Levy and M. Litt. Subsequent research varied the monomer side chains and refined controlled polymerization, creating a broad family with tunable thermal and solution behavior. Commercial and biomedical development followed different paths. Polymer Chemistry Innovations markets the poly(2-ethyl-2-oxazoline) member as Aquazol for binding applications including ceramics, while academic researchers such as Richard Hoogenboom and collaborators have advanced systematic understanding of the family’s structures and properties and its potential in biomedical materials. Aquazol’s history applies to that particular member, rather than every poly(2-oxazoline).', [s('glassner-pox-history','ghent-university','open_journal','M. Glassner, M. Vergaelen and R. Hoogenboom. Poly(2-oxazoline)s: A comprehensive overview of polymer structures and their physical properties. Ghent University author manuscript.','https://backoffice.biblio.ugent.be/download/8543992/8620228','Introduction; cationic ring-opening polymerization section; references 1–4 for the 1966–1967 founding papers.'),s('pci-aquazol-history','polymer-chemistry-innovations','manufacturer_technical_document','Polymer Chemistry Innovations. Frequently asked questions.','https://www.polychemistry.com/faq/','Aquazol identity as poly(2-ethyl-2-oxazoline), product position and binder applications.')]);
add(237, 'PVP’s industrial history is associated with Walter Reppe’s development of its manufacturing process at BASF around 1940. BASF’s 2015 account marked 75 years since that work and separately recorded production of the vinylpyrrolidone precursor at Ludwigshafen from 1939. The polymer became a versatile formulation ingredient: pharmaceutical tablet excipients were marketed under Kollidon, hair-styling products under Luviskol, and detergent ingredients under Sokalan. Later uses included water-treatment and dialysis membranes and specialty adhesives in the Luvitec range. BASF’s 2015 announcement of planned capacity additions in Germany, the United States and China illustrates continuing industrial investment. Brand ranges include different compositions and grades, so their application histories do not establish identical behavior for every PVP material.', [s('basf-pvp-history','basf','manufacturer_technical_document','BASF. BASF plans worldwide expansion of PVP production (22 January 2015).','https://www.basf.com/dam/jcr%3Ae500b457-caa7-37c5-9470-2c0f4a700fef/basf/www/global/documents/en/news-and-media/news-releases/2015/01/P120e_PVP%20expansion.pdf','Pages 1–2: planned expansion; Walter Reppe, precursor-production dates and commercial application ranges.')]);
add(238, 'The PEO–PPO–PEO triblock family emerged from industrial work on nonionic surfactants in the early 1950s. Lester G. Lundsted’s Wyandotte Chemicals patent, filed in 1953 and granted in 1954, describes adding ethylene oxide to polypropylene-oxide chains to tune water affinity and surface activity. Detergent and related formulation uses were central to that development. Irving R. Schmolka later explored concentrated aqueous gels at BASF Wyandotte; his patent, filed in 1966 and granted in 1973, described applications including pharmaceutical and cosmetic preparations. The progression from surface-active blocks to gel-forming formulations became an important part of poloxamer development. These patent dates distinguish early block-copolymer manufacturing from later application inventions.', [s('lundsted-poloxamer-history','wyandotte-chemicals','patent','L. G. Lundsted. Polyoxyalkylene compounds. US2674619A (1954).','https://patents.google.com/patent/US2674619A/en','Bibliographic data; Description and claim 18: ethylene oxide/propylene oxide blocks and surface-active uses.'),s('schmolka-poloxamer-history','basf-wyandotte','patent','I. R. Schmolka. Aqueous gels. US3740421A (1973).','https://patents.google.com/patent/US3740421A/en','Bibliographic data; Description and examples: aqueous EO–PO–EO gels, pharmaceutical and cosmetic preparations.')]);
add(239, 'PAMAM dendrimers originated in Donald Tomalia’s Dow Chemical research program. Tomalia and Jean Fréchet’s historical account dates discovery of the acrylate-based divergent synthesis to 1979 and its development to 1979–1985, with contributors including Jim Dewald, George Kallos and Jesse Roeck. Public disclosure began at a 1983 Gordon Research Conference, followed by fuller publications in 1984–1985. Stepwise construction made molecular size, branching and terminal groups systematic design variables. Commercial Starburst materials subsequently supplied research into host–guest chemistry and drug solubilization. Dendritic Nanotechnologies and other suppliers helped disseminate these research reagents. Investigations of encapsulated anticancer and anti-inflammatory compounds illustrate later biomedical exploration; they should not be read as proof of clinical adoption of the entire PAMAM family.', [s('tomalia-pamam-history','tomalia-frechet','open_journal','D. A. Tomalia and J. M. J. Fréchet. Discovery of dendrimers and dendritic polymers: A brief historical perspective. Journal of Polymer Science Part A: Polymer Chemistry 40 (2002), 2719–2728.','https://web.mit.edu/course/10/10.569/www/Tomaliadendrhistory.pdf','Pages 2721–2723: 1979–1985 Dow program, research team and early public disclosures.'),s('sigma-pamam-delivery','sigma-aldrich','manufacturer_technical_document','Sigma-Aldrich. Solubility Enhancement with Dendrimers.','https://www.sigmaaldrich.com/US/en/technical-documents/technical-article/materials-science-and-engineering/drug-delivery/solubility-enhancement','Starburst PAMAM commercial research materials and drug-encapsulation examples.')]);
add(240, 'PDMS belongs to the methyl-silicone industry that developed around improved organosilicon chemistry and electrical insulation. In his oral history, Eugene G. Rochow describes methyl-silicone experiments at General Electric in 1938 and the direct-synthesis breakthrough in 1940 that enabled industrial preparation of its precursors. These are broader silicone milestones rather than a single invention date for every PDMS form. Commercial development produced silicone oils and curable rubbers, while later manufacturing work improved precursor hydrolysis and by-product recovery. A new research role expanded during the 1990s: Younan Xia and George Whitesides’ 1998 review documents PDMS elastomers, including Dow Corning materials, as stamps and molds for soft lithography. This connected an established silicone platform to microfabrication and analytical-device research.', [s('rochow-silicone-history','science-history-institute','institutional_reference','Science History Institute. Oral history interview with Eugene G. Rochow.','https://digital.sciencehistory.org/works/z316q265z','Transcript pages 24–27: methyl silicones and insulation; pages 37–39: 1940 direct synthesis and 1941 patent application.'),s('pdms-industrial-process-history','wacker','patent','B. Pachaly, G. Nagy, W. Jacques and R. Christa. Process for preparing polydimethylsiloxanes. US5476916A (1995).','https://patents.google.com/patent/US5476916A/en','Background and Summary: silicone oils/rubbers, continuous industrial hydrolysis and hydrogen-chloride recovery.'),s('xia-whitesides-pdms-history','harvard-university','open_journal','Y. Xia and G. M. Whitesides. Soft Lithography. Annual Review of Materials Science 28 (1998), 153–184.','https://www.gmwgroup.harvard.edu/sites/g/files/omnuum10006/files/gmwgroup/files/604.pdf','Pages 156–159: PDMS elastomers and commercial materials; soft-lithography methods and applications.')]);

export default records;
